interface Element { accept(v: Visitor): void }
interface Visitor { visitA(a: A): void; visitB(b: B): void }
class A implements Element { accept(v: Visitor) { v.visitA(this) } }
class B implements Element { accept(v: Visitor) { v.visitB(this) } }

interface Node {}
class TextNode implements Node { constructor(public text: string) {} }
class ElementNode implements Node { constructor(public tag: string, public children: Node[]) {} }
class Renderer {
  render(n: Node): string {
    if (n instanceof TextNode) return n.text
    if (n instanceof ElementNode) return `<${n.tag}>` + n.children.map(c => this.render(c)).join('') + `</${n.tag}>`
    return ''
  }
}

// Version A: put operations as methods on node classes
abstract class NodeA {
  abstract render(): string
  abstract validate(): boolean
}
class TextNodeA extends NodeA { constructor(public text: string) { super() } render() { return this.text } validate() { return this.text.length > 0 } }

// Version B: extract operations into operation objects with accept
interface OperationB { visitText(n: TextNodeB): any; visitElement(n: ElementNodeB): any }
class TextNodeB { constructor(public text: string) {} accept(op: OperationB) { return op.visitText(this) } }
